// Domain types for the M1 app: thin names, in design-doc vocabulary, over the types generated from
// api/openapi.yaml (src/lib/api/schema.d.ts, regenerated by `sh api/generate.sh`, never hand-edited).
import type { components } from './api/schema';

type S = components['schemas'];

export type Bill = S['Bill'];
export type BillSummary = S['BillSummary'];
/** One catalog entry: every bill, tracked or not (design/01 Public catalog). */
export type CatalogEntry = S['CatalogEntry'];
export type VersionSummary = S['VersionSummary'];
/** The text of one official version, with sections, lines, and anchors. */
export type OfficialVersion = S['Version'];
export type Referral = S['Referral'];
export type Section = S['Section'];
export type SectionResource = S['SectionResource'];
export type Line = S['Line'];
export type LineRangeResource = S['LineRangeResource'];
export type AddressInfo = S['AddressInfo'];
export type Explanation = S['Explanation'];
export type Provenance = S['Provenance'];
export type ExplanationFlag = Explanation['flags'][number];
export type BillSummaryDoc = S['BillSummaryDoc'];
export type VersionChangeSummary = S['VersionChangeSummary'];
export type Statement = S['Statement'];
export type Citation = S['Citation'];
export type VersionComparison = S['VersionComparison'];
export type ComparisonSection = S['ComparisonSection'];
export type SelectionPolicy = S['SelectionPolicy'];
export type LogEntry = S['LogEntry'];
export type ContentClass = S['ContentClass'];
export type Link = S['Link'];
export type Problem = S['Problem'];

/** A line range inside one section of one official version (design/10 Canonical addresses). */
export interface Anchor {
	billId: string;
	/** Version code, for example "eh". */
	version: string;
	sectionId: string;
	from: number;
	to: number;
}
